/** Start and end photo URLs for a library exercise, or null when the dataset has no match. */
export function exerciseImages(name: string): [string, string] | null {
  const id = MEDIA_ID[name];
  return id ? [`${BASE_URL}/${id}/0.jpg`, `${BASE_URL}/${id}/1.jpg`] : null;
}
